-- Тема 04: варианты ответов выровнены по длине и форме (80 исправлений в 37 вопросах), ключи не меняются.
-- Источник: scripts/questions/075_option_length_topic04.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Что означает свойство транзакций «атомарность»?', 'Транзакция выполняется полностью или не выполняется вовсе', 'Транзакция выполняется целиком или никак', 'Всё или ничего.', 'Всё или ничего: при ошибке отменяются все изменения транзакции.'),
        ('option', 'Какая информация нужна планировщику, чтобы выбрать хороший план запроса?', 'Правила переписывания запросов', 'Правила переписывания запросов из каталога', 'Правила применяются раньше, на этапе переписывания.', NULL),
        ('option', 'Какая информация нужна планировщику, чтобы выбрать хороший план запроса?', 'Журнал предзаписи', 'Журнал предзаписи за последние сутки', 'Журнал нужен для восстановления, а не для планирования.', NULL),
        ('option', 'Какая информация нужна планировщику, чтобы выбрать хороший план запроса?', 'Статистика о размере таблиц и распределении данных', 'Статистика о данных в таблицах', 'По статистике оцениваются число строк и стоимость вариантов.', 'Статистика о размере таблиц и распределении данных: по ней оцениваются число строк и стоимость вариантов.'),
        ('option', 'Какая информация нужна планировщику, чтобы выбрать хороший план запроса?', 'Список активных сеансов', 'Список активных сеансов на сервере', 'Активные сеансы на выбор плана не влияют.', NULL),
        ('option', 'Где размещаются разобранные запросы, состояние курсоров и место для сортировок?', 'В буферном кеше', 'В буферном кеше общей памяти', 'Буферный кеш хранит страницы данных и находится в общей памяти.', NULL),
        ('option', 'Когда стоит использовать менеджер пула соединений, например pgBouncer?', 'Когда клиентов слишком много или соединения открываются и закрываются слишком часто', 'Когда клиентов много или они часто переподключаются', 'Пул снижает затраты на процессы и частые подключения.', 'Когда клиентов слишком много или соединения открываются и закрываются слишком часто: пул снижает затраты на процессы и подключения.'),
        ('option', 'Когда стоит использовать менеджер пула соединений, например pgBouncer?', 'Чтобы заменить репликацию', 'Чтобы заменить репликацию между серверами', 'Репликация решает другую задачу.', NULL),
        ('option', 'Когда стоит использовать менеджер пула соединений, например pgBouncer?', 'Чтобы включить шифрование трафика', 'Чтобы включить шифрование трафика клиентов', 'Шифрование трафика настраивается через SSL.', NULL),
        ('option', 'Какой размер страницы данных обычно используется и как его изменить?', '8 КБ, изменить можно только при сборке сервера', '8 КБ, меняется при сборке сервера', 'Размер задаётся при сборке и одинаков для всего кластера.', 'Размер задаётся при сборке и одинаков для всего кластера; изменить его можно только пересборкой.'),
        ('option', 'Что хранится в локальной памяти обслуживающего процесса?', 'Буферный кеш', 'Буферный кеш сервера', 'Буферный кеш находится в общей памяти.', NULL),
        ('option', 'Что означает свойство транзакций «согласованность»?', 'Транзакция переводит базу из одного согласованного состояния в другое, соблюдая ограничения', 'Транзакция сохраняет ограничения целостности базы', 'Согласованность — соблюдение установленных ограничений целостности.', 'Транзакция переводит базу из одного согласованного состояния в другое, соблюдая установленные ограничения целостности.'),
        ('option', 'Кто, как правило, управляет транзакциями: решает, какие команды в неё входят и когда её фиксировать или отменять?', 'Процесс postmaster', 'Серверный процесс postmaster', 'Он запускает процессы и следит за ними, а не управляет транзакциями.', NULL),
        ('option', 'Что делает этап переписывания запроса?', 'Выполняет запрос и возвращает результат', 'Выполняет запрос и возвращает строки клиенту', 'Это этап выполнения.', NULL),
        ('option', 'Что делает этап переписывания запроса?', 'Выбирает способ выполнения, например использовать ли индекс', 'Выбирает способ выполнения запроса', 'Это этап планирования.', NULL),
        ('option', 'Что делает этап переписывания запроса?', 'Преобразует запрос, например подставляет вместо имени представления его запрос', 'Преобразует запрос, например раскрывает представления', 'Свои преобразования можно задать механизмом правил.', 'Например, подставляет вместо имени представления его запрос; свои преобразования можно задать механизмом правил.'),
        ('option', 'Где хранится системный каталог — описание объектов базы данных?', 'В журнале предзаписи', 'В журнале предзаписи сервера', 'Журнал хранит записи об изменениях для восстановления.', NULL),
        ('option', 'Где хранится системный каталог — описание объектов базы данных?', 'Только в памяти процесса postmaster', 'В памяти процесса postmaster, без диска', 'Каталог хранится на диске, в памяти процессов лишь его кеш.', NULL),
        ('option', 'Где хранится системный каталог — описание объектов базы данных?', 'В самой базе данных, в специальных таблицах', 'В специальных таблицах самой базы', 'Поэтому к нему можно обращаться обычными запросами SQL.', 'Системный каталог хранится в самой базе данных, в специальных таблицах, поэтому к нему можно обращаться обычными запросами SQL.'),
        ('option', 'Где хранится системный каталог — описание объектов базы данных?', 'В файле postgresql.conf', 'В файле postgresql.conf кластера', 'Там хранятся параметры конфигурации.', NULL),
        ('option', 'Что делает postmaster, если какой-нибудь процесс сервера завершился аварийно?', 'Останавливает сервер до ручного запуска', 'Останавливает сервер до запуска администратором', 'При настройке по умолчанию (restart_after_crash = on) сервер восстанавливается автоматически, без участия администратора.', NULL),
        ('option', 'Что делает postmaster, если какой-нибудь процесс сервера завершился аварийно?', 'Ничего: клиент сам переподключится', 'Ничего: клиент сам переподключится к серверу', 'postmaster следит за порождёнными процессами и реагирует на сбой.', NULL),
        ('option', 'Что делает postmaster, если какой-нибудь процесс сервера завершился аварийно?', 'Перезапускает упавший процесс или, если он мог повредить общие данные, весь сервер', 'Перезапускает процесс, а при угрозе общей памяти — весь сервер', 'Так postmaster «присматривает» за процессами; восстановление после сбоя работает при restart_after_crash = on (по умолчанию).', NULL),
        ('option', 'Какой процесс выполняет аутентификацию подключающегося клиента?', 'postmaster', 'Процесс postmaster при приёме подключения', 'Он принимает подключение и порождает обслуживающий процесс, а аутентифицирует уже тот.', NULL),
        ('option', 'Какой процесс выполняет аутентификацию подключающегося клиента?', 'Обслуживающий процесс (backend), порождённый для этого клиента', 'Обслуживающий процесс, порождённый для клиента', 'После этого клиент общается уже с ним.', NULL),
        ('option', 'Какой процесс выполняет аутентификацию подключающегося клиента?', 'Менеджер пула pgBouncer', 'Менеджер пула соединений pgBouncer', 'Пул необязателен, аутентификацию выполняет сервер.', NULL),
        ('option', 'Нужен ли перезапуск сервера для установки большинства расширений?', 'Только при сборке из исходных кодов', 'Да, если сервер собран из исходных кодов', 'Способ установки сервера на это не влияет.', NULL),
        ('option', 'Нужен ли перезапуск сервера для установки большинства расширений?', 'Нет, большинство расширений устанавливается «на лету»', 'Нет, большинство ставится на работающий сервер', 'Благодаря этому расширений существует очень много.', 'Большинство расширений устанавливается «на лету»; перезапуск нужен лишь тем, что загружаются при старте сервера.'),
        ('option', 'Нужен ли перезапуск сервера для установки большинства расширений?', 'Да, всегда', 'Да, после установки любого расширения', 'Перезапуск нужен лишь некоторым, которые загружаются при старте сервера.', NULL),
        ('option', 'В каком режиме клиент-серверного протокола клиент может подготовить запрос средствами самого протокола, без команды SQL PREPARE?', 'Режим только для чтения', 'Режим транзакций для чтения', 'Такого режима протокола нет.', NULL),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Клиенты по очереди используют одни и те же обслуживающие процессы, поэтому нельзя рассчитывать на сохранение сеансового состояния, например подготовленных операторов', 'Нельзя полагаться на сохранение состояния сеанса', 'Да. Соединение закрепляется за клиентом только на время транзакции, затем возвращается в пул, и следующая транзакция может попасть в другой обслуживающий процесс. Поддержка подготовленных операторов зависит от версии и настроек PgBouncer.', 'Клиенты по очереди используют одни и те же обслуживающие процессы: соединение закрепляется за клиентом только на время транзакции, поэтому сеансовое состояние, например подготовленные операторы, может не сохраниться. Поддержка подготовленных операторов зависит от версии и настроек PgBouncer.'),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Клиенты подключаются напрямую к postmaster', 'Клиенты подключаются напрямую к процессу postmaster', 'Клиенты подключаются к менеджеру пула.', NULL),
        ('option', 'Что нужно учитывать приложению, работающему через менеджер пула соединений в режиме пула транзакций (например, PgBouncer)?', 'Транзакции через пул не поддерживаются', 'Транзакции через такой пул не поддерживаются вовсе', 'Нет. В режиме пула транзакций обычные транзакции работают: соединение закрепляется за клиентом до их завершения.', NULL),
        ('option', 'Что такое пользовательская функция в PostgreSQL?', 'Именованная подпрограмма на сервере с объявленным типом результата, которую можно вызвать из SQL', 'Именованная подпрограмма на сервере, вызываемая из SQL', 'Функция создаётся в базе; её аргументы и результат описываются при объявлении.', 'Функция создаётся в базе; её аргументы и тип результата описываются при объявлении.'),
        ('option', 'Что такое пользовательская функция в PostgreSQL?', 'Параметр конфигурации, действующий только до конца транзакции', 'Параметр конфигурации, действующий до конца транзакции', 'Параметры управляют работой сервера и не являются функциями.', NULL),
        ('option', 'В базе определена функция app.add_tax(numeric), возвращающая numeric. Что делает запрос SELECT app.add_tax(100);?', 'Переименовывает аргумент функции в 100', 'Переименовывает аргумент этой функции в 100', '100 — передаваемое значение, а не новое имя аргумента.', NULL),
        ('option', 'В базе определена функция app.add_tax(numeric), возвращающая numeric. Что делает запрос SELECT app.add_tax(100);?', 'Создаёт новую функцию с именем add_tax', 'Создаёт новую функцию с именем add_tax в app', 'Функции создаёт CREATE FUNCTION.', NULL),
        ('option', 'В базе определена функция app.add_tax(numeric), возвращающая numeric. Что делает запрос SELECT app.add_tax(100);?', 'Вызывает функцию с аргументом 100 и выводит её результат', 'Вызывает функцию с аргументом 100 и выводит результат', 'Вызов функции используется как выражение в SELECT.', NULL),
        ('option', 'Какие формы результата может иметь пользовательская функция PostgreSQL при соответствующем объявлении?', 'Только целое число, используемое как код завершения ОС', 'Целое число, используемое как код завершения ОС', 'Функции SQL не ограничены моделью кодов завершения процессов.', NULL),
        ('option', 'Какие формы результата может иметь пользовательская функция PostgreSQL при соответствующем объявлении?', 'Всегда ровно одну строку: наборы строк запрещены', 'Ровно одну строку: наборы строк запрещены', 'RETURNS SETOF и RETURNS TABLE позволяют возвращать наборы.', NULL),
        ('option', 'Что такое процедура, создаваемая командой CREATE PROCEDURE?', 'Синоним функции, которую всегда вызывают только внутри SELECT', 'Синоним функции, которую вызывают внутри SELECT', 'Для процедуры используется CALL, а не вызов как выражения SELECT.', NULL),
        ('option', 'Что такое процедура, создаваемая командой CREATE PROCEDURE?', 'Хранимая подпрограмма для выполнения действий, вызываемая командой CALL', 'Подпрограмма для выполнения действий, вызываемая CALL', 'Процедура — самостоятельный вид подпрограммы базы данных.', NULL),
        ('option', 'Что такое триггер в PostgreSQL?', 'Объект, связывающий событие в базе с автоматическим вызовом триггерной функции', 'Объект, вызывающий функцию при событии в базе', 'Например, изменение строки таблицы может запускать заданную функцию.', 'Триггер связывает событие в базе с автоматическим вызовом триггерной функции: например, изменение строки таблицы может запускать заданную функцию.'),
        ('option', 'На обычной несекционированной таблице есть один включённый триггер AFTER UPDATE FOR EACH ROW без WHEN, его функция не выполняет действий, вызывающих повторное срабатывание. Одна команда UPDATE изменила 10 строк, других триггеров нет. Сколько раз он сработает?', 'Ни разу, потому что AFTER означает только после COMMIT', 'Ни разу: AFTER-триггер ждёт фиксации транзакции', 'Обычный AFTER-триггер не означает ожидание фиксации транзакции.', NULL),
        ('option', 'Какие утверждения об обычных триггерах таблиц верны?', 'BEFORE INSERT FOR EACH ROW может изменить значения NEW перед вставкой', 'BEFORE ROW-триггер может изменить NEW перед вставкой', 'Триггерная функция может вернуть изменённую новую строку.', 'Триггерная функция BEFORE INSERT FOR EACH ROW может вернуть изменённую новую строку.'),
        ('option', 'Какие утверждения об обычных триггерах таблиц верны?', 'AFTER-триггер всегда работает в новой транзакции после COMMIT', 'AFTER-триггер работает в новой транзакции после COMMIT', 'Обычный AFTER-триггер не создаёт отдельную транзакцию после фиксации.', NULL),
        ('option', 'Какие утверждения об обычных триггерах таблиц верны?', 'Триггер срабатывает только после ручной команды CALL', 'Триггер срабатывает после ручной команды CALL', 'Срабатывание определяется событием, указанным при создании триггера.', NULL),
        ('option', 'Какие утверждения об обычных триггерах таблиц верны?', 'Триггерная функция выполняется в той же транзакции, что и вызвавшая её команда', 'Триггерная функция выполняется в транзакции команды', 'Её изменения не становятся отдельной независимо фиксируемой транзакцией.', 'Она выполняется в той же транзакции, что и вызвавшая её команда; её изменения не становятся отдельной транзакцией.'),
        ('option', 'Для чего в базе данных нужен индекс?', 'Для дополнительного пути доступа, который может ускорить поиск нужных строк', 'Для дополнительного пути доступа к нужным строкам', 'Подходящий индекс позволяет избежать просмотра всей таблицы в некоторых запросах.', 'Индекс — дополнительный путь доступа, который может ускорить поиск нужных строк: подходящий индекс позволяет не просматривать всю таблицу.'),
        ('option', 'На столбце есть подходящий индекс, но PostgreSQL выбирает последовательное сканирование таблицы. Обязательно ли это ошибка?', 'Нет: планировщик мог оценить последовательное сканирование как более дешёвое', 'Нет: последовательное чтение могло быть оценено дешевле', 'Например, при чтении большой доли таблицы индекс может не дать выигрыша.', NULL),
        ('option', 'На email создан обычный уникальный индекс без условия WHERE. Что произойдёт при попытке вставить вторую строку с тем же ненулевым email обычным INSERT без ON CONFLICT, если триггеры не изменяют и не отменяют вставляемую строку?', 'Индекс будет автоматически удалён', 'Индекс будет автоматически удалён сервером', 'Конфликт данных не удаляет индекс.', NULL),
        ('option', 'На email создан обычный уникальный индекс без условия WHERE. Что произойдёт при попытке вставить вторую строку с тем же ненулевым email обычным INSERT без ON CONFLICT, если триггеры не изменяют и не отменяют вставляемую строку?', 'Вставка будет отклонена из-за нарушения уникальности', 'Вставка будет отклонена с ошибкой уникальности', 'Уникальный индекс не допускает одинаковые ненулевые ключи.', NULL),
        ('option', 'Какой встроенный тип индекса обычно подходит для сравнений целых чисел как на равенство, так и на диапазон: =, <, <=, >, >=?', 'Любой индекс поддерживает только равенство', 'GIN', 'Поддерживаемые операции зависят от метода доступа.', 'GIN рассчитан на составные значения: массивы, jsonb, полнотекстовый поиск. Для сравнения целых чисел без расширения btree_gin он не подходит.'),
        ('option', 'Клиент каждый раз отправляет полный текст обычного SELECT сообщением простого протокола, без PREPARE и EXECUTE. Какие этапы обработки проходит запрос при каждой такой отправке?', 'Только выполнение: разобранный текст сервер хранит с прошлой отправки', 'Выполнение: разобранный текст сервер хранит с прошлой отправки', 'Разобранный запрос хранится только у подготовленного оператора, а здесь его нет.', NULL),
        ('option', 'Клиент каждый раз отправляет полный текст обычного SELECT сообщением простого протокола, без PREPARE и EXECUTE. Какие этапы обработки проходит запрос при каждой такой отправке?', 'Разбор, переписывание, планирование и выполнение — все этапы каждый раз', 'Все этапы: разбор, переписывание, планирование, выполнение', 'Такой запрос не связан ни с чем сохранённым, поэтому каждая отправка обрабатывается заново.', NULL),
        ('option', 'Таблица t (id int PRIMARY KEY) пуста. Выполнена команда psql -c "INSERT INTO t VALUES (1); INSERT INTO t VALUES (1);" без BEGIN в тексте. Что окажется в таблице?', 'Ничего: обе команды ушли одним сообщением простого протокола и выполнялись в одной транзакции, ошибка второй отменила и первую', 'Ничего: обе вставки шли в одной транзакции и откатились', 'В этом примере обе вставки входят в одну неявную транзакцию: в тексте нет BEGIN и COMMIT, и блок транзакции не открыт. Ошибка второй откатывает первую.', 'Обе команды ушли одним сообщением простого протокола и выполнялись в одной неявной транзакции: в тексте нет BEGIN и COMMIT. Ошибка второй вставки откатила и первую.'),
        ('option', 'Таблица t (id int PRIMARY KEY) пуста. Выполнена команда psql -c "INSERT INTO t VALUES (1); INSERT INTO t VALUES (1);" без BEGIN в тексте. Что окажется в таблице?', 'Команда не выполнится: в одном сообщении можно отправить только один запрос', 'Команда не выполнится: в сообщении допустим один запрос', 'Простой протокол допускает несколько команд через точку с запятой; одну команду допускает сообщение Parse расширенного протокола.', NULL),
        ('option', 'Таблица t (id int PRIMARY KEY) пуста. Выполнена команда psql -c "INSERT INTO t VALUES (1); INSERT INTO t VALUES (1);" без BEGIN в тексте. Что окажется в таблице?', 'Одна строка: первая команда зафиксирована отдельно, вторая завершилась ошибкой', 'Одна строка: первая вставка зафиксирована отдельно', 'Так было бы при отдельных запросах с включённым AUTOCOMMIT и без открытого блока транзакции: например, интерактивный psql отправляет команды по одной, даже если они набраны в одной строке.', NULL),
        ('option', 'Таблица t (id int PRIMARY KEY) пуста. Выполнена команда psql -c "INSERT INTO t VALUES (1); INSERT INTO t VALUES (1);" без BEGIN в тексте. Что окажется в таблице?', 'Две строки: в одном сообщении первичный ключ проверяется только в конце', 'Две строки: ключ проверяется в конце сообщения', 'Первичный ключ проверяется сразу при вставке строки, а даже отложенная проверка не позволила бы зафиксировать повтор.', NULL),
        ('option', 'Что происходит при выполнении команды PREPARE и затем EXECUTE этого подготовленного оператора?', 'PREPARE выполняет разбор и переписывание; при EXECUTE строится план или берётся сохранённый общий, и запрос выполняется', 'PREPARE — разбор и переписывание, EXECUTE — план и выполнение', 'Подготовка экономит повторный разбор и переписывание, а при общем плане — и планирование.', 'При EXECUTE строится план или берётся сохранённый общий, и запрос выполняется. Подготовка экономит повторный разбор и переписывание, а при общем плане — и планирование.'),
        ('option', 'Что происходит при выполнении команды PREPARE и затем EXECUTE этого подготовленного оператора?', 'PREPARE только запоминает текст; разбор, переписывание и планирование выполняются при каждом EXECUTE', 'PREPARE запоминает текст, остальное — при каждом EXECUTE', 'Тогда подготовка ничего бы не экономила; разбор и переписывание выполняются при PREPARE.', NULL),
        ('option', 'Что происходит при выполнении команды PREPARE и затем EXECUTE этого подготовленного оператора?', 'PREPARE строит план; разбор и переписывание повторяются при каждом EXECUTE', 'PREPARE строит план, разбор повторяется при каждом EXECUTE', 'PREPARE выполняет разбор и переписывание, а планирование — при EXECUTE, если нельзя взять сохранённый общий план.', NULL),
        ('option', 'Что происходит при выполнении команды PREPARE и затем EXECUTE этого подготовленного оператора?', 'PREPARE выполняет все этапы, включая выполнение; EXECUTE возвращает сохранённый результат', 'PREPARE выполняет запрос, EXECUTE отдаёт результат', 'Результат не сохраняется: EXECUTE каждый раз выполняет запрос заново и видит данные по правилам видимости текущей транзакции.', NULL),
        ('option', 'Что верно о подготовленном операторе, созданном командой PREPARE?', 'Подготовленные операторы своего сеанса показывает представление pg_prepared_statements', 'Операторы своего сеанса показывает pg_prepared_statements', 'В нём видны имя, текст, время создания и сколько раз выбирался общий и частный план (generic_plans, custom_plans).', NULL),
        ('option', 'Что верно о подготовленном операторе, созданном командой PREPARE?', 'Он сохраняется между транзакциями до конца сеанса, если его не освободить раньше', 'Он живёт до конца сеанса, если его не освободить раньше', 'Освобождает оператор команда DEALLOCATE, а все операторы сеанса сразу — DISCARD ALL.', NULL),
        ('option', 'Как команда PREPARE q(integer) AS SELECT * FROM t WHERE id = $1 соотносится со стандартом SQL?', 'Это команда psql, сервер её не понимает', 'Это метакоманда psql, сервер её не понимает', 'PREPARE выполняет сервер; команды psql начинаются с обратной косой черты.', NULL),
        ('option', 'Как команда PREPARE q(integer) AS SELECT * FROM t WHERE id = $1 соотносится со стандартом SQL?', 'Это расширение PostgreSQL: в стандарте PREPARE есть только для встроенного SQL и с другим синтаксисом', 'Это расширение PostgreSQL, в стандарте синтаксис другой', 'Так сказано в разделе о совместимости в документации к PREPARE.', 'В стандарте PREPARE есть только для встроенного SQL и с другим синтаксисом: так сказано в разделе о совместимости в документации к PREPARE.'),
        ('option', 'Как команда PREPARE q(integer) AS SELECT * FROM t WHERE id = $1 соотносится со стандартом SQL?', 'Команда описана в стандарте SQL и одинаково работает во всех СУБД', 'Описана в стандарте SQL и работает везде одинаково', 'Синтаксис подготовки операторов в разных СУБД различается; приложения обычно готовят операторы через драйвер.', NULL),
        ('option', 'Что означает свойство транзакций «изоляция»?', 'Транзакции всегда выполняются строго по очереди, одна за другой', 'Транзакции выполняются строго по очереди, одна за другой', 'Транзакции выполняются параллельно; даже Serializable лишь гарантирует для зафиксированных транзакций результат, как при каком-то последовательном выполнении.', NULL),
        ('option', 'Что означает свойство транзакций «изоляция»?', 'Параллельно выполняемые транзакции влияют друг на друга только в пределах, которые допускает их уровень изоляции', 'Транзакции влияют друг на друга в пределах уровня изоляции', 'В PostgreSQL для этого служат снимки данных и блокировки, а на уровне Serializable — ещё и отслеживание зависимостей между транзакциями.', 'Параллельно выполняемые транзакции влияют друг на друга только в пределах, которые допускает их уровень изоляции. В PostgreSQL для этого служат снимки данных и блокировки, а на уровне Serializable — ещё и отслеживание зависимостей.'),
        ('option', 'В psql с настройками по умолчанию открыта транзакция; после SAVEPOINT s очередная команда завершилась ошибкой. Что верно?', 'Следующие обычные команды сервер отклонит, пока транзакцию не откатят полностью или до точки сохранения', 'Обычные команды отклоняются до отката транзакции или к точке', 'Ошибка переводит транзакцию в прерванное состояние; в стандартном приглашении psql появляется знак !.', NULL),
        ('option', 'В psql с настройками по умолчанию открыта транзакция; после SAVEPOINT s очередная команда завершилась ошибкой. Что верно?', 'Если сразу выполнить COMMIT, сервер откатит всю транзакцию и ответит ROLLBACK', 'Сразу выполненный COMMIT откатит всю транзакцию', 'Прерванную транзакцию зафиксировать нельзя: отменятся и изменения, сделанные до ошибки.', NULL),
        ('option', 'В psql с настройками по умолчанию открыта транзакция; после SAVEPOINT s очередная команда завершилась ошибкой. Что верно?', 'Команда ROLLBACK TO s отменит изменения после точки сохранения, и транзакцию можно продолжить', 'ROLLBACK TO s отменит изменения после точки, транзакция продолжится', 'Изменения, сделанные до точки сохранения, останутся в транзакции, но будут зафиксированы только вместе с ней.', NULL),
        ('option', 'В psql выполнено \set AUTOCOMMIT off, затем команда INSERT INTO t VALUES (1); и больше ничего. Увидит ли эту строку другой сеанс?', 'Да, но только после того, как другой сеанс сам выполнит COMMIT', 'Да, после того как другой сеанс выполнит COMMIT', 'Чужой COMMIT не фиксирует изменения нашей транзакции; зафиксировать их может только наш сеанс.', NULL),
        ('option', 'В psql выполнено \set AUTOCOMMIT off, затем команда INSERT INTO t VALUES (1); и больше ничего. Увидит ли эту строку другой сеанс?', 'Нет: при AUTOCOMMIT off команды изменения данных запрещены до явного BEGIN', 'Нет: при AUTOCOMMIT off изменения запрещены до BEGIN', 'Команда выполнилась; запрета нет, просто транзакция осталась открытой.', NULL),
        ('option', 'В psql выполнено \set AUTOCOMMIT off, затем команда INSERT INTO t VALUES (1); и больше ничего. Увидит ли эту строку другой сеанс?', 'Нет: psql сам открыл транзакцию перед INSERT, и пока не выполнен COMMIT, изменение не зафиксировано', 'Нет: psql открыл транзакцию, а COMMIT не выполнен', 'Если транзакция ещё не открыта, psql при AUTOCOMMIT off отправляет BEGIN перед INSERT. Изменение останется незафиксированным до явного COMMIT, а ROLLBACK его отменит.', 'Если транзакция ещё не открыта, psql при AUTOCOMMIT off сам отправляет BEGIN перед INSERT. Изменение останется незафиксированным до явного COMMIT, а ROLLBACK его отменит.'),
        ('option', 'Сеанс 1 выполнил BEGIN и вставил новую строку, но COMMIT ещё не выполнил. Кто видит эту строку?', 'Все сеансы сразу после вставки', 'Все сеансы сразу после выполнения вставки', 'Незафиксированные изменения чужих транзакций не видны ни на одном уровне изоляции.', NULL),
        ('option', 'Сеанс 1 выполнил BEGIN и вставил новую строку, но COMMIT ещё не выполнил. Кто видит эту строку?', 'Только сам сеанс 1: другим сеансам незафиксированная строка не видна', 'Только сам сеанс 1, другим она не видна', 'Следующие команды транзакции видят её собственную вставку ещё до COMMIT.', NULL),
        ('option', 'Как устроена страница обычной таблицы в PostgreSQL?', 'В начале заголовок и массив указателей на версии строк, сами версии размещаются от конца страницы, свободное место — между ними', 'Заголовок и указатели в начале, версии строк — с конца', 'Массив указателей растёт от начала страницы, область версий строк — навстречу ему. Для вставки нужно, чтобы хватило места на версию строки и её указатель.', 'В начале заголовок и массив указателей на версии строк, сами версии размещаются от конца страницы, свободное место — между ними. Массив указателей растёт от начала, область версий — навстречу ему.'),
        ('option', 'Что можно добавить в PostgreSQL расширениями, не меняя исходный код сервера?', 'Ничего: расширение устанавливается только пересборкой сервера', 'Ничего: расширение устанавливается пересборкой сервера', 'После установки файлов объекты расширения создают в базе командой CREATE EXTENSION, пересборка не нужна. Отдельным модулям нужна загрузка при запуске сервера (shared_preload_libraries) и перезапуск.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
